window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-12191\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσρέω,</h1><div class=\"entry-meta\"><span>DGP · ordem 952 na letra ε · nº geral 12191</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ἐσρέω (fut. εἰσρυήσομαι, aor.2 εἰσερρύην) fluir em direção a; escoar; afluir, εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-12192\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσροή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 953 na letra ε · nº geral 12192</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fluxo; escoamento para ou em. 〈ἐσρέω〉</p></section></article>\n<article id=\"entry-dgp-12193\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἱστήκη</h1><div class=\"entry-meta\"><span>DGP · ordem 954 na letra ε · nº geral 12193</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἵστημι.</p></section></article>\n<article id=\"entry-dgp-12194\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰστίθημι,</h1><div class=\"entry-meta\"><span>DGP · ordem 955 na letra ε · nº geral 12194</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ἐστίθημι 1 colocar; pôr algo, ac., em ou sobre, εἰς e ac.: Κροῖσον ἐς τὰς χεῖρας ἐσθεὶς τῷ ἑωυτοῦ παιδὶ Καμβύσῃ her. tendo [Ciro] colocado Creso nas mãos de seu filho Cambises 2 pôr alguém a bordo; fazer alguém embarcar ♦ méd. 3 pôr com cuidado alguém, ac., em ou sobre, εἰς e ac. 4 fazer embarcar para si: ἐσθέμενοι τέκνα καὶ γυναῖκας her. tendo embarcado suas crianças e mulheres.</p></section></article>\n<article id=\"entry-dgp-12195\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰστοξεύω,</h1><div class=\"entry-meta\"><span>DGP · ordem 956 na letra ε · nº geral 12195</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ἐστοξεύω 1 lançar flechas em ou sobre, εἰς e ac. 2 tard. lançar como flechas ♦ méd. 3 (paixão) cravar-se como uma flecha.</p></section></article>\n<article id=\"entry-dgp-12196\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰστρέχω,</h1><div class=\"entry-meta\"><span>DGP · ordem 957 na letra ε · nº geral 12196</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ἐστρέχω (fut. εἰσθρέξομαι, aor.2 εἰσέ­δραμον) correr; precipitar-se em ou para, ac. ou εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-12197\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσφέρω,</h1><div class=\"entry-meta\"><span>DGP · ordem 958 na letra ε · nº geral 12197</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ἐσφέρω (fut. εἰσοίσω, aor.2 εἰσήνεγκον, perf. εἰσενήνοχα etc.) ativa 1 levar; trazer; introduzir algo ou alguém, ac., em ou para, dat. ou εἰς e ac. 2 levar como contribuição ou pagamento; fornecer; pagar 3 apresentar; expor; propor decisão média 4 levar consigo 5 introduzir para si 6 levar ao interior do corpo; ingerir; absorver passiva 7 introduzir-se; entrar; penetrar 1 πόλεμον γὰρ εἰσήνεγκεν Ἑλλήνων χθονί eur. pois levou a guerra à terra dos helenos, τινὰς εἰς τὰς ναῦς εἰσήνεγκαν xen. conduziram alguns a bordo 2 φημὶ δὴ δεῖν ὑμᾶς εἰσφέρειν χρήματα dem. eu digo que vós deveis dar vossas riquezas como contribuição, εἰσφορὰς δὲ πολλὰς καὶ μεγάλας εἰσενήνοχεν lís. ele pagou muitas e grandes contribuições, συνεχώρησαν δ᾽ εἰσοίσειν ἄλλα χίλια καὶ διακόσια τάλαντα pol. eles consentiram em depositar como tributo outros mil e duzentos talentos, πάντες γὰρ ἡμεῖς Σωκράτει εἰσοίσομεν plat. pois todos nós nos cotizaremos por Sócrates 3 τοὺς λόγους γὰρ ἐσφέρεις καινοὺς ἀεὶ eur. pois apresentas sempre novos discursos, Μεγάβυζος μὲν δὴ ταύτῃ γνώμην ἐσέφερε her. Megabizo expôs uma opinião no mesmo sentido, ἐντεῦθεν ἐκκλησίαν ἐποίουν εἰς ἣν ἡ Βουλὴ εἰσήνεγκε τὴν ἑαυτῆς γνώμην xen. em seguida reuniram a assembléia em que o Senado apresentou sua própria decisão, οὐκέτι εἰσήνεγκαν περὶ Ἀργείων ἐς τὰς βουλὰς tuc. não mais propuseram decisões, nos conselhos, sobre os afazeres argivos 4 ἦν δὲ αὐτοῖς νόμιμον μηδὲ προχοΐδας εἰσφέρεσθαι εἰς τὰ συμπόσια xen. era um costume deles nem levar penicos aos banquetes, βότρυος ὑγρὸν πῶμ᾽ ηὗρε κεἰσηνέγκατο θνητοῖς eur. [Baco] descobriu a bebida líquida da uva e a introduziu entre os mortais, πολλὰς πευκὰς ἐσφέρεται hom. [o rio] leva muitos pinheiros com ele 5 ἐσενεγκάμενοι σῖτόν τε καὶ ὅσα πλεῖστα ἐδύναντο χρήσιμα tuc. após terem introduzido para si trigo e tantas outras provisões quantas podiam 6 μηδέποτε βαρυνθῆναι τὴν γαστέρα ὑπὸ σιτίων, ὁπόσον ἂν πλῆθος εἰσενέγκηται a.lib que jamais sentisse o estômago pesado de alimentos, qualquer quantidade que ingerisse 7 τοὺς ἐς τὴν ὕλην ἐσφερομένους xen. os que penetram na floresta.</p></section></article>\n<article id=\"entry-dgp-12198\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσφορά,</h1><div class=\"entry-meta\"><span>DGP · ordem 959 na letra ε · nº geral 12198</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ant. ἐσφορά, ᾶς (ἡ) 1 contribuição 2 depósito; imposto 3 introdução 4 apresentação; proposta (de lei), gen. 〈εἰσφέρω〉</p></section></article>\n<article id=\"entry-dgp-12199\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσφορέω-ῶ,</h1><div class=\"entry-meta\"><span>DGP · ordem 960 na letra ε · nº geral 12199</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ἐσφορέω trazer ou levar a, εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-12200\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσφρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 961 na letra ε · nº geral 12200</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. εἰσέφρουν, fut. εἰσφρήσω, aor. εἰσέφρησα, perf. desus.) 1 deixar entrar; introduzir; admitir; acolher 2 ingerir; engolir 3 entrar; penetrar ♦ méd. 4 introduzir para si.</p></section></article>\n<article id=\"entry-dgp-12201\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσχειρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 962 na letra ε · nº geral 12201</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. 3ª sing. εἰσεχείρισεν) confiar algo, ac., a alguém, dat.</p></section></article>\n<article id=\"entry-dgp-12202\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσχέω,</h1><div class=\"entry-meta\"><span>DGP · ordem 963 na letra ε · nº geral 12202</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ἐσχέω 1 verter; derramar ♦ pas. 2 derramar-se.</p></section></article>\n<article id=\"entry-dgp-12203\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 964 na letra ε · nº geral 12203</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e át. ant. ἔσω adv. 1 (lugar) dentro; para o interior ou no interior: στείχειν ἔσω sóf. avançar para o interior, πᾶν δ᾽ εἴσω ἔδυ ξίφος hom. a lança penetrou inteira no interior, τὸ εἴσω ou τὰ εἴσω no interior 2 (tempo) durante esse tempo ♦ prep. 3 no ou para o interior de; dentro de, ac. ou gen.: δῦναι δόμον Ἄιδος εἴσω hom. mergulhou no interior da casa de Hades, ὁ δ᾽ εἴσω δώματος ᾔει hom. ia no interior da casa.</p></section></article>\n<article id=\"entry-dgp-12204\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴσωθεν,</h1><div class=\"entry-meta\"><span>DGP · ordem 965 na letra ε · nº geral 12204</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ἔσωθεν adv. de dentro.</p></section></article>\n<article id=\"entry-dgp-12205\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσωθέω-ῶ,</h1><div class=\"entry-meta\"><span>DGP · ordem 966 na letra ε · nº geral 12205</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ἐσωθέω-ῶ at. e méd. empurrar para dentro.</p></section></article>\n<article id=\"entry-dgp-12206\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰσωπός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 967 na letra ε · nº geral 12206</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que está diante de; que está à vista de; visível. 〈εἰς, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-12207\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἶτα</h1><div class=\"entry-meta\"><span>DGP · ordem 968 na letra ε · nº geral 12207</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 (tempo ou sucessão) depois; em seguida: πρῶτον μὲν...εἶτα..., εἶτα primeiro..., depois..., em seguida 2 então; e então; nessas condições: εἶτ᾽ ἐγὼ οὐ φρονῶ; eur. então, eu não tenho bom senso? εἶτ᾽ οὐκ αἰσχυνόμεθα; isócr. e então, não nos envergonhamos? 3 (op. ou contradição) em seguida: μή μοι προτείνων κέρδος εἶτ᾽ ἀποστέρει ésql. não comeces apresentando-me uma vantagem para em seguida me privares (dela).</p></section></article>\n<article id=\"entry-dgp-12208\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἷται</h1><div class=\"entry-meta\"><span>DGP · ordem 969 na letra ε · nº geral 12208</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. perf. méd. de ἕννυμι.</p></section></article>\n<article id=\"entry-dgp-12209\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἵτε</h1><div class=\"entry-meta\"><span>DGP · ordem 970 na letra ε · nº geral 12209</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª pl. aor.2 de ἵημι.</p></section></article>\n<article id=\"entry-dgp-12210\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἶτε</h1><div class=\"entry-meta\"><span>DGP · ordem 971 na letra ε · nº geral 12210</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª pl. pres. opt. de εἰμί.</p></section></article>\n<article id=\"entry-dgp-12211\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴτε</h1><div class=\"entry-meta\"><span>DGP · ordem 972 na letra ε · nº geral 12211</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">conj. 1 εἴτε... εἴτε se... ou se:; em poesia, o primeiro εἴτε pode estar omitido: αἰνεῖν εἴτε με ψέγειν θέλεις ésql. se queres me elogiar ou me censurar 2 em inter. ind., εἴτε... εἴτε se...ou se: σκοπεῖτ᾽ εἴτ᾽ ὀρθῶς λογίζομαι εἴτε μή dem. examinai se raciocino bem ou mal. 〈εἰ, τε〉</p></section></article>\n<article id=\"entry-dgp-12212\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴτην</h1><div class=\"entry-meta\"><span>DGP · ordem 973 na letra ε · nº geral 12212</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª dual pres. opt. de εἰμί.</p></section></article>\n<article id=\"entry-dgp-12213\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἶφ᾽</h1><div class=\"entry-meta\"><span>DGP · ordem 974 na letra ε · nº geral 12213</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εἶπε em elisão, diante de vogal aspirada.</p></section></article>\n<article id=\"entry-dgp-12214\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴφ᾽</h1><div class=\"entry-meta\"><span>DGP · ordem 975 na letra ε · nº geral 12214</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εἰπέ, em elisão, diante de vogal aspirada.</p></section></article>\n<article id=\"entry-dgp-12215\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἶχον</h1><div class=\"entry-meta\"><span>DGP · ordem 976 na letra ε · nº geral 12215</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἔχω.</p></section></article>\n<article id=\"entry-dgp-12216\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴχοσαν</h1><div class=\"entry-meta\"><span>DGP · ordem 977 na letra ε · nº geral 12216</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. impf. ind. at. tard. de ἔχω.</p></section></article>\n<article id=\"entry-dgp-12217\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 978 na letra ε · nº geral 12217</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª sing. pres. subj. ép. de ἐάω.</p></section></article>\n<article id=\"entry-dgp-12218\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴωθα</h1><div class=\"entry-meta\"><span>DGP · ordem 979 na letra ε · nº geral 12218</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf.2 com sent. de pres. (m.-q.-perf. εἰώθειν com sent. de impf., part. εἰωθώς) 1 estar habituado a; ter hábito de, inf. ♦ εἰωθώς, υῖα, ός 2 habitual; costumeiro: ἐν τῷ εἰωτότι τρόπῳ plat. na maneira habitual ♦ τὸ εἰωθός 3 costume; hábito: παρὰ τὸ εἰωθός contrariamente ao costume, κατὰ τὸ εἰωθός conforme o costume.</p></section></article>\n<article id=\"entry-dgp-12219\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰώθειν</h1><div class=\"entry-meta\"><span>DGP · ordem 980 na letra ε · nº geral 12219</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. εἴωθα.</p></section></article>\n<article id=\"entry-dgp-12220\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰωθότως</h1><div class=\"entry-meta\"><span>DGP · ordem 981 na letra ε · nº geral 12220</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. segundo o costume; habitualmente. 〈εἰωθώς〉</p></section></article>\n<article id=\"entry-dgp-12221\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰωθώς, υῖα, ός</h1><div class=\"entry-meta\"><span>DGP · ordem 982 na letra ε · nº geral 12221</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. εἴωθα.</p></section></article>\n<article id=\"entry-dgp-12222\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰῶμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 983 na letra ε · nº geral 12222</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª pl. pres. subj. ép. de ἐάω.</p></section></article>\n<article id=\"entry-dgp-12223\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἴων</h1><div class=\"entry-meta\"><span>DGP · ordem 984 na letra ε · nº geral 12223</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐάω.</p></section></article>\n<article id=\"entry-dgp-12224\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἵως</h1><div class=\"entry-meta\"><span>DGP · ordem 985 na letra ε · nº geral 12224</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἕως2.</p></section></article>\n<article id=\"entry-dgp-12225\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εἰῶσι</h1><div class=\"entry-meta\"><span>DGP · ordem 986 na letra ε · nº geral 12225</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. pres. ind. e subj. ép. de ἐάω.</p></section></article>\n<article id=\"entry-dgp-12226\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκ</h1><div class=\"entry-meta\"><span>DGP · ordem 987 na letra ε · nº geral 12226</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, diante de vogal, ἐξ advérbio 1 separado do verbo, em poesia, fora; fora de; fazendo sair preposição com genitivo 2 (lugar) de, indicando deslocamento de dentro para fora, saída, escape, vinda para a superfície 3 (lugar) de; a partir de, indicando proveniência, afastamento, mudança 4 (tempo) desde; a partir de, indicando deslocamento ou desenvolvimento a partir de um tempo inicial 5 (tempo) depois de; logo depois de; após, indicando subseqüência, posterioridade 6 (tempo) em, indicando um momento no tempo 7 (origem) de; por mão de; por obra de, indicando origem por descendência, por criação ou doação; por, em poesia, introduzindo o agente da pas. 8 (causa) a partir de; por causa de 9 (conseqüência) a partir de; em conseqüência de 10 (matéria) a partir de; de 11 (meio ou instrumento) a partir de; por meio de; por 12 (extração) a partir de; dentre; entre 13 (conformidade) conforme; segundo 14 (preço) por 15 locuções 1 ἐκ δ᾽ ἔσσυτο λαός hom. e a multidão lançou-se para fora, ἐκ δ᾽ ἄγαγε κλισίης Βρισηΐδα hom. conduziu Briseida para fora da barraca, ἐκ δ᾽ εὐνὰς ἔβαλον hom. lançaram fora as âncoras 2 ἄνθρωπον ἐξιέναι ἐκ γῆς εἰς φῶς plat. que o homem saísse da terra para a luz, ἐξ οἴκων μολεῖν sóf. a partir de casa, αἴ κε φύγῃσιν δηΐου ἐκ πολέμοιο hom. se ele escapar da guerra perniciosa, τὰ ἐκ τῆς γῆς φυόμενα xen. o que é produzido da terra, ἄλλ᾽ εἴπερ ἐκ τῆς καρδίας μ᾽ ὄντως φιλεῖς, ὦ παῖ, πιθοῦ ar. mas se me amas verdadeiramente do fundo do teu coração, meu filho, obedece-me 3 δαῖέ οἱ ἐκ κόρυθος τε καὶ ἀσπίδος πῦρ hom. do seu elmo e escudo [Atena] fazia brilhar um fogo, ἐκ χειρὸς παίειν xen. dar golpe com a mão, ἐκ χρυσῶν φιαλῶν πίνειν xen. beber de copos de ouro, Ἕκτορα δ᾽ ἐκ βελέων ὕπαγε Ζεύς hom. Zeus tira Heitor da mira dos dardos, πλούσιος ἐκ πτωχοῦ γεγονώς dem. de pobre tornou-se rico, μοι δέχεται κακὸν ἐκ κακοῦ hom. para mim de um mal advém um mal 4 ἐξ ἀρχῆς hom. desde o começo, ἐκ νέου plat. desde a juventude, ἐκ μικροῦ παιδαρίου dem. a partir da primeira infância, ἐξ οὗ hom. ou ἐξ ὅτου xen. desde quando, ἐκ τοῦ hom. ou ἐκ τοῖο hom. ou ἐξ ἐκείνου tuc. desde então, ἐκ πολλοῦ tuc. desde há muito tempo, ἐξ ὀλίγου tuc. desde há pouco, recentemente, ἐκ παλαιοτάτου tuc. desde os tempos mais remotos 5 ἐκ τοῦ ἀρίστου προήγαγεν ὁ Χειρίσοφος τὸ στράτευμα xen. após o jantar, Quirísofo levou o exército avante, γελάσαι ἐκ τῶν ἔμπροσθεν δακρύων xen. rir após as lágrimas de antes, ἐκ μὲν εἰρήνης πολεμεῖν, ἐκ δὲ πολέμου πάλιν ξυμβῆναι tuc. após a paz, entrar em guerra, após a guerra, fazer tratados 6 ἐκ νυκτῶν hom. de noite, ἐκ νυκτός xen. de noite, ἐξ ἡμέρας sóf. de dia 7 ὦ παῖ πατρὸς ἐξ Ἀχιλλέως sóf. ó filho do pai Aquiles, τὸν ἐξ ἐμῆς μητρός sóf. o filho de minha mãe, καὶ γὰρ τ᾽ ὄναρ ἐκ Διός ἐστιν hom. pois o sonho vem de Zeus, ὅσσαι γὰρ νύκτες τε καὶ ἡμέραι ἐκ Διός εἰσι hom. tanto os dias como as noites são de Zeus, τὸν ἐκ τῶν Ἑλλήνων εἰς τοὺς βαρβάρους φόβον xen. o terror inspirado pelos helenos aos bárbaros, τὰ ἐντεταγμένα ἐκ τοῦ Μάγου her. as ordens vindas do Mago 8 Ἥρη, ἐξ ἧς ἀθανάτοισιν ἔρις καὶ νεῖκος ἐφῆπται hom. Hera, por causa de quem a discórdia e a hostilidade estão atadas aos imortais, ἐκ φόβου του sóf. por medo de alguém, ἐκ νόσου plut. por causa de uma doença 9 ἐκ τῶν ὁμολογουμένων τοῦτο σκεπτέον plat. a partir do que foi acordado, é preciso examinar isso 10 οὐκ ἐξ ξύλων ποιεῦνται τὰ πλοῖα ἀλλ᾽ ἐκ διφθερέων her. não fazem seus barcos a partir de madeira, mas de peles, ἐκ κριθῶν μέθυ ésql. vinho de cevada 11 ὡς ἐκ βίας μ᾽ ἄξοντες ἢ λόγοις πάλιν; sóf. tendo a idéia de me levar de volta pela força ou por argumentos? 12 ἐξ Ἀθηναίων οἱ ἄριστοι tuc. os melhores dentre os atenienses, δεινόν τι ποιησάμενος κεῖνον μοῦνον ἐξ ἁπάντων σωθῆναι her. tendo considerado como algo terrível que, dentre todos, só ele tenha sido salvo 13 ἐκ τοῦ δικαίου οἰκονομεῖν xen. administrar conforme a regra, ἐκ τῶν λογίων her. em conformidade com os oráculos, ἐκ τῶν ἔργων κρινόμενοι xen. julgados conforme os seus atos 14 συμφωνήσας μετὰ τῶν ἐργάτων ἐκ δηναρίου τὴν ἡμέραν n.t. tendo combinado com os operários por um denário por dia 15 ἐξ ἀέλπτου her. inesperadamente, ἐκ τοῦ ἐμφανέος her., ἐκ τοῦ προδήλου sóf. ou ἐκ τοῦ φανεροῦ, ἐκ τοῦ προφανοῦς tuc. à vista de todos, abertamente, ἐκ τῆς ἰθέης her. em linha reta, diretamente, ἐκ νέης her. novamente, ἐξ ὑστέρης her. em seguida, por último, ἐκ ταχείας sóf. com rapidez, velozmente, ἐξ ἑκουσίας sóf. voluntariamente, ἐξ ἀνάγκης sóf. forçosamente, ἐκ βίας sóf. com violência, com força, ἐξ ἴσου ou ἐκ τοῦ ἴσου sóf. por igual, igualmente, ἐξ ἑτοίμου plut. prontamente, ἐξ ἅπαντος luc. em particular, ἐκ τύχης cár. por acaso.</p></section></article>\n<article id=\"entry-dgp-12227\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑκάβη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 988 na letra ε · nº geral 12227</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Hécuba, esposa de Príamo.</p></section></article>\n<article id=\"entry-dgp-12228\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκάεργος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 989 na letra ε · nº geral 12228</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que age por si mesmo, por sua própria vontade; livre ou hábil na ação, epít. de Apolo. 〈ἑκάς, εἴργω〉</p></section></article>\n<article id=\"entry-dgp-12229\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκάην</h1><div class=\"entry-meta\"><span>DGP · ordem 990 na letra ε · nº geral 12229</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. καίω.</p></section></article>\n<article id=\"entry-dgp-12230\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκαβέατο</h1><div class=\"entry-meta\"><span>DGP · ordem 991 na letra ε · nº geral 12230</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. impf. jôn. de κάθημαι.</p></section></article>\n<article id=\"entry-dgp-12231\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκαθεζόμην</h1><div class=\"entry-meta\"><span>DGP · ordem 992 na letra ε · nº geral 12231</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. καθέζομαι.</p></section></article>\n<article id=\"entry-dgp-12232\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕκαθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 993 na letra ε · nº geral 12232</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de longe ♦ prep. 2 londe de, gen. 〈ἑκάς, -θεν〉</p></section></article>\n<article id=\"entry-dgp-12233\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκάθευδον</h1><div class=\"entry-meta\"><span>DGP · ordem 994 na letra ε · nº geral 12233</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. καθεύδω.</p></section></article>\n<article id=\"entry-dgp-12234\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκαθήμην</h1><div class=\"entry-meta\"><span>DGP · ordem 995 na letra ε · nº geral 12234</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κάθημαι.</p></section></article>\n<article id=\"entry-dgp-12235\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκάθηρα</h1><div class=\"entry-meta\"><span>DGP · ordem 996 na letra ε · nº geral 12235</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. καθαίρω.</p></section></article>\n<article id=\"entry-dgp-12236\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκάθιζον, ἐκάθισα</h1><div class=\"entry-meta\"><span>DGP · ordem 997 na letra ε · nº geral 12236</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. e aor. de καθίζω.</p></section></article>\n<article id=\"entry-dgp-12237\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑκάλειος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 998 na letra ε · nº geral 12237</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habitante ou originário de Hecale; hecaleu, epít. de Zeus.</p></section></article>\n<article id=\"entry-dgp-12238\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκάλεσα,</h1><div class=\"entry-meta\"><span>DGP · ordem 999 na letra ε · nº geral 12238</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐκάλεσσα aor. de καλέω. Ἡκάλη, ης (ἡ) 1 Hecale, anciã que cuidou de Teseu na juventude 2 Hecale, demo ático.</p></section></article>\n<article id=\"entry-dgp-12239\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑκαλῆθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1000 na letra ε · nº geral 12239</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de Hecale. 〈 Ἑκάλη, -θεν〉</p></section></article>\n<article id=\"entry-dgp-12240\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑκαλήσιον, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1001 na letra ε · nº geral 12240</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">festa de Zeus de Hecale. 〈 Ἡκάλειος〉</p></section></article>\n<article id=\"entry-dgp-12241\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑκαλίνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1002 na letra ε · nº geral 12241</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Hecaline, pequena Hecale. 〈 Ἑκάλη〉</p></section></article>\n<article id=\"entry-dgp-12242\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἕκαλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1003 na letra ε · nº geral 12242</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Ἑκάλειος.</p></section></article>\n<article id=\"entry-dgp-12243\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκαμον</h1><div class=\"entry-meta\"><span>DGP · ordem 1004 na letra ε · nº geral 12243</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κάμνω.</p></section></article>\n<article id=\"entry-dgp-12244\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔκανον</h1><div class=\"entry-meta\"><span>DGP · ordem 1005 na letra ε · nº geral 12244</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. καίνω.</p></section></article>\n<article id=\"entry-dgp-12245\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκάρην</h1><div class=\"entry-meta\"><span>DGP · ordem 1006 na letra ε · nº geral 12245</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. κείρω.</p></section></article>\n<article id=\"entry-dgp-12246\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκάς,</h1><div class=\"entry-meta\"><span>DGP · ordem 1007 na letra ε · nº geral 12246</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ἕκας (comp. ἑκατέρω, superl. ἐκαστάτω) adv. 1 longe; ao longe: οὐχ ἑκάς που sóf. em algum lugar não longe, ἐκὰς ἀπό τινος hom. longe de qualquer coisa ♦ prep. 2 (lugar) longe de, gen.: νηῶν ἐκάς hom. longe das naus 3 (tempo) logo após, gen.: οὐκ ἑκὰς χρόνου her. pouco tempo após, sem tardar.</p></section></article>\n<article id=\"entry-dgp-12247\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκαστάτω</h1><div class=\"entry-meta\"><span>DGP · ordem 1008 na letra ε · nº geral 12247</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl. de ἑκάς.</p></section></article>\n<article id=\"entry-dgp-12248\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκασταχόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1009 na letra ε · nº geral 12248</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de todo lado. 〈ἕκαστος, -θεν〉</p></section></article>\n<article id=\"entry-dgp-12249\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκασταχόθι</h1><div class=\"entry-meta\"><span>DGP · ordem 1010 na letra ε · nº geral 12249</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em cada lugar; por toda parte. 〈ἕκαστος, -θι〉</p></section></article>\n<article id=\"entry-dgp-12250\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκασταχοῖ</h1><div class=\"entry-meta\"><span>DGP · ordem 1011 na letra ε · nº geral 12250</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em cada lugar; por toda parte. 〈ἕκαστος, -ι〉</p></section></article>\n<article id=\"entry-dgp-12251\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκασταχόσε</h1><div class=\"entry-meta\"><span>DGP · ordem 1012 na letra ε · nº geral 12251</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. = ἐκασταχοῖ. 〈ἕκαστος, -σε〉</p></section></article>\n<article id=\"entry-dgp-12252\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκασταχοῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 1013 na letra ε · nº geral 12252</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. por toda parte; em todo lugar. 〈ἕκαστος, -ου〉</p></section></article>\n<article id=\"entry-dgp-12253\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκαστέρω</h1><div class=\"entry-meta\"><span>DGP · ordem 1014 na letra ε · nº geral 12253</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comp. de ἑκάς.</p></section></article>\n<article id=\"entry-dgp-12254\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκάστοθι</h1><div class=\"entry-meta\"><span>DGP · ordem 1015 na letra ε · nº geral 12254</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em todo lugar.</p></section></article>\n<article id=\"entry-dgp-12255\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕκαστος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1016 na letra ε · nº geral 12255</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">usado no sing., mesmo com verbo no plural, se a atribuição é a um indivíduo, e não a um grupo 1 cada um, no nom., em posição absoluta ou junto de εἷς, τις, πᾶς, αὐτός: ἔβαν οἰκόνδε ἕκαστος hom. cada um foi para sua casa, ἔμενον κατὰ χώρην ἕκαστοι her. cada povo ficou no seu país, ἕκαστοι τὴν ἑαυτῶν ἀπολείποντες tuc. cada povo abandonando a própria terra, ὅστις ἕκαστοι her. todo aquele que 2 cada, nos casos oblíquos, junto de pron. ou de subst. ou com prep.: ὅττι κεν ὔμμι κακὸν πέμπῃσιν ἑκάστῳ hom. o mal que ele envia a cada um de vós, τῆς ἡμέρας ἑκάστης tuc. cada dia, ἕκαστον τὸ ζεῦγος xen. cada jugo, καθ᾽ ἑκάστην ἡμέραν xen. a cada dia, ταύτας μίαν ἐπ᾽ ἡμέρῃ ἐκάστῃ αἵρεε her. essas [cidades] a cada dia conquistava uma 3 com ὡς, cada um por si, em separado; cada um à parte: ὡς ἕκαστος ἐδύνατο tuc. como cada um podia, ὡς ἑκάστῳ ἔργον προστάσσων her. fixando uma tarefa a cada um em particular.</p></section></article>\n<article id=\"entry-dgp-12256\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκάστοτε</h1><div class=\"entry-meta\"><span>DGP · ordem 1017 na letra ε · nº geral 12256</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. a todo momento; a cada vez. 〈ἕκαστος, τε〉</p></section></article>\n<article id=\"entry-dgp-12257\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐκατέατο</h1><div class=\"entry-meta\"><span>DGP · ordem 1018 na letra ε · nº geral 12257</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. impf. jôn. de κάθημαι.</p></section></article>\n<article id=\"entry-dgp-12258\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατεράκις</h1><div class=\"entry-meta\"><span>DGP · ordem 1019 na letra ε · nº geral 12258</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. cada uma de duas vezes. 〈ἑκάτερος, -ακίς〉</p></section></article>\n<article id=\"entry-dgp-12259\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκάτερθε,</h1><div class=\"entry-meta\"><span>DGP · ordem 1020 na letra ε · nº geral 12259</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">diante de vogal ἑκάτερθεν adv. de cada lado.</p></section></article>\n<article id=\"entry-dgp-12260\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκάτερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1021 na letra ε · nº geral 12260</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cada um dos dois; um e outro: ἀπῆλθον ἑκάτερος ἐπὶ τὰ προσήκοντα xen. partiram cada um para seus deveres 2 no pl., ref. a dois grupos, cada um dos dois; uns e outros: ἐδικαίουν αὐτοὶ ἑκάτεροι her. julgavam uns e outros. 〈ἑκάς〉</p></section></article>\n<article id=\"entry-dgp-12261\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατέρωθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 1022 na letra ε · nº geral 12261</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de dois lados; de um e de outro lado; de cada lado, gen. 〈ἑκάτερος, -θεν〉</p></section></article>\n<article id=\"entry-dgp-12262\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατέρωθι</h1><div class=\"entry-meta\"><span>DGP · ordem 1023 na letra ε · nº geral 12262</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em cada um dos dois lados. 〈ἑκάτερος, -θι〉</p></section></article>\n<article id=\"entry-dgp-12263\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατέρωσε</h1><div class=\"entry-meta\"><span>DGP · ordem 1024 na letra ε · nº geral 12263</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em duas direções; pelos dois lados. 〈ἑκάτερος〉</p></section></article>\n<article id=\"entry-dgp-12264\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑκάτη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1025 na letra ε · nº geral 12264</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Hécate, divindade que preside à magia e aos encantamentos. 〈ἕκατος〉</p></section></article>\n<article id=\"entry-dgp-12265\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατηβελέτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1026 na letra ε · nº geral 12265</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) = ἑκατηβόλος.</p></section></article>\n<article id=\"entry-dgp-12266\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατηβόλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1027 na letra ε · nº geral 12266</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que lança longe seus dardos. 〈ἕκατος, βέλος〉</p></section></article>\n<article id=\"entry-dgp-12267\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑκατήσιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1028 na letra ε · nº geral 12267</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Hecatésion, estátua de Hécate. 〈 Ἑκάτη〉</p></section></article>\n<article id=\"entry-dgp-12268\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕκατι,</h1><div class=\"entry-meta\"><span>DGP · ordem 1029 na letra ε · nº geral 12268</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e ép. ἕκητι adv. 1 por vontade de, gen. 2 por causa de; por, gen. 3 quanto a; em relação a, gen.</p></section></article>\n<article id=\"entry-dgp-12269\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατογκάρανος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1030 na letra ε · nº geral 12269</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cem cabeças. 〈ἑκατόν, κάρηνον〉</p></section></article>\n<article id=\"entry-dgp-12270\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατόγχειρ, χειρος</h1><div class=\"entry-meta\"><span>DGP · ordem 1031 na letra ε · nº geral 12270</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) = ἑκατόγχειρος.</p></section></article>\n<article id=\"entry-dgp-12271\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατόγχειρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1032 na letra ε · nº geral 12271</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cem braços. 〈ἑκατόν, χείρ〉</p></section></article>\n<article id=\"entry-dgp-12272\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατόζυγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1033 na letra ε · nº geral 12272</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com cem assentos para os remadores; muito grande. 〈ἑκατόν, ζυγός〉</p></section></article>\n<article id=\"entry-dgp-12273\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑκατομβαιών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1034 na letra ε · nº geral 12273</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Hecatombeon, 1º mês do calendário ático (2ª metade de julho e 1ª metade de agosto). 〈ἐκατόμβη〉</p></section></article>\n<article id=\"entry-dgp-12274\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατόμβη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1035 na letra ε · nº geral 12274</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sacrifício de cem bois; hecatombe 2 grande sacrifício público. 〈ἐκατόν, βοῦς〉</p></section></article>\n<article id=\"entry-dgp-12275\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατόμβοιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1036 na letra ε · nº geral 12275</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 no valor de cem bois; de preço alto 2 no valor de cem peças de moeda com a efígie de um boi. 〈ἑκατόμβη〉</p></section></article>\n<article id=\"entry-dgp-12276\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατόμπεδος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1037 na letra ε · nº geral 12276</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de cem pés de extensão ♦ ὁ, ἡ ἑκατόμπεδος 2 hecatômpedo, templo com cem pés de extensão. 〈ἑκατόν, ποῦς〉</p></section></article>\n<article id=\"entry-dgp-12277\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατόμποδος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1038 na letra ε · nº geral 12277</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἑκατόμπεδος.</p></section></article>\n<article id=\"entry-dgp-12278\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατόμπολις, ις, ι</h1><div class=\"entry-meta\"><span>DGP · ordem 1039 na letra ε · nº geral 12278</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ιος de cem cidades. 〈ἑκατόν, πόλις〉</p></section></article>\n<article id=\"entry-dgp-12279\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατόμπους, ους, ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 1040 na letra ε · nº geral 12279</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ποδος de cem pés. 〈ἑκατόν, ποῦς〉</p></section></article>\n<article id=\"entry-dgp-12280\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατόμπυλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1041 na letra ε · nº geral 12280</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cem portas. 〈ἑκατόν, πύλη〉</p></section></article>\n<article id=\"entry-dgp-12281\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατομφόνια, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 1042 na letra ε · nº geral 12281</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sacrifício oferecido pela morte de cem inimigos. 〈ἑκατόν, φόνος〉</p></section></article>\n<article id=\"entry-dgp-12282\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατόν</h1><div class=\"entry-meta\"><span>DGP · ordem 1043 na letra ε · nº geral 12282</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">num. card. indecl. 1 cem, 100 2 cem, como quantia indeterminada; grande quantidade; muito: ζώσατο δὲ ζώνῃ ἑκατὸν θυσάνας ἀραρυίῃ hom. cingiu-se com cinto guarnecido de cem borlas.</p></section></article>\n<article id=\"entry-dgp-12283\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατονταέτης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 1044 na letra ε · nº geral 12283</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cem anos; secular. 〈ἑκατόν, ἔτος〉</p></section></article>\n<article id=\"entry-dgp-12284\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατονταπλασίων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 1045 na letra ε · nº geral 12284</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος cem vezes mais; que é cêntuplo de, gen. 〈ἑκατόν, πλασίων〉</p></section></article>\n<article id=\"entry-dgp-12285\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατοντάρχης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1046 na letra ε · nº geral 12285</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comandante de cem homens; centurião. 〈ἑκατόν, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-12286\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατόνταρχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1047 na letra ε · nº geral 12286</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἑκατοντάρχης.</p></section></article>\n<article id=\"entry-dgp-12287\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατοντάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1048 na letra ε · nº geral 12287</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o número cem; centena. 〈ἑκατόν〉</p></section></article>\n<article id=\"entry-dgp-12288\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατοντάχειρ, χειρος</h1><div class=\"entry-meta\"><span>DGP · ordem 1049 na letra ε · nº geral 12288</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) de cem mãos. 〈ἑκατόν, χείρ〉</p></section></article>\n<article id=\"entry-dgp-12289\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑκατοντούτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 1050 na letra ε · nº geral 12289</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de cem anos; centenário. 〈ἑκατόν, ἔτος〉</p></section></article>\n<article id=\"entry-dgp-12290\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕκατος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1051 na letra ε · nº geral 12290</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o que fere ao longe, epít. de Apolo. 〈ἑκάς〉</p></section></article>\n";
